{
  "name": "文件管理器",
  "name_en": "File Manager",
  "manufacturer": "",
  "description": "这是实验软件中的文件管理界面，用于浏览、打开、删除和定位实验相关的文件与文件夹，例如采集数据、图像结果或脚本目录。它不是独立的实验硬件设备，而是实验控制系统中的文件操作组件。",
  "description_en": "This is a file management interface within laboratory software, used to browse, open, delete, and locate experiment-related files and folders such as acquired data, image outputs, or script directories. It is not a standalone piece of lab hardware, but a file-operation component in the lab control system.",
  "tag_hints": [
    "file management",
    "data browsing",
    "experiment data files",
    "folder navigation",
    "lab software UI"
  ],
  "actions": [
    {
      "action_name": "auto-checkAndOpenItem",
      "description": "检查并打开指定的文件或文件夹项目",
      "description_en": "Check and open the specified file or folder item"
    },
    {
      "action_name": "auto-deleteItem",
      "description": "删除指定的文件或文件夹项目",
      "description_en": "Delete the specified file or folder item"
    },
    {
      "action_name": "auto-setRootPath",
      "description": "设置根目录路径",
      "description_en": "Set the root directory path"
    },
    {
      "action_name": "auto-browse",
      "description": "浏览并选择文件或目录",
      "description_en": "Browse and select a file or directory"
    },
    {
      "action_name": "auto-openRootInOS",
      "description": "在操作系统文件管理器中打开根目录",
      "description_en": "Open the root directory in the operating system file explorer"
    }
  ]
}

